de: {
  'btn.puzzle.title': 'Aufgaben (kein Zug, einsperren, zählen)',
  'pz.title': 'Amazons-Aufgaben', 'pz.desc': 'Lass den Gegner ohne Zug, sperr eine gegnerische Amazone ein, gewinn das Zählen eines geteilten Bretts. Alle Lösungen sind exakt aus den Regeln berechnet; der Gegner verteidigt sich so zäh wie möglich.',
  'pz.grpWin': 'Kein Zug mehr', 'pz.grpWinSub': 'Wie zäh die Verteidigung auch ist: Mach alle gegnerischen Amazonen in den vorgegebenen Zügen bewegungsunfähig.',
  'pz.grpTac': 'Einsperren', 'pz.grpTacSub': 'Finde die gegnerische Amazone mit nur einem Ausgang und schließ ihn.',
  'pz.grpEnd': 'Endspiel', 'pz.grpEndSub': 'Ist das Brett in Räume geteilt, zählen nur noch die Züge. Finde den Zug, der kein Feld verschenkt.',
  'pz.th.w1': 'Kein Zug in 1', 'pz.th.w1.sub': 'Schließ die letzten freien Felder mit dem Zielfeld der Amazone und ihrem Pfeil.',
  'pz.th.w2': 'Kein Zug in 2', 'pz.th.w2.sub': 'Lies die Antwort voraus und vollende im zweiten Zug.',
  'pz.th.t1': 'Sperr sie ein', 'pz.th.t1.sub': 'Schließ den letzten Ausgang der leuchtenden gegnerischen Amazone.',
  'pz.th.e1': 'Zählen', 'pz.th.e1.sub': 'Weiß hat genau einen Zug mehr als Schwarz. Ein verschenktes Feld verliert.',
  'pz.winIn': 'Kein Zug in {n}', 'pz.goal': '{c} am Zug: Lass den Gegner in {n} ohne Zug',
  'pz.goal.trap': '{c} am Zug: Sperr die leuchtende gegnerische Amazone ein', 'pz.goal.end': '{c} am Zug: Nutz deinen Raum ohne Verlust und halte länger durch',
  'pz.hint1': 'Noch {n}. Zähl die freien Felder rund um die gegnerischen Amazonen – ein Zug schließt höchstens zwei (Zielfeld und Pfeil).',
  'pz.h1.trap': 'Welches Feld neben der leuchtenden Amazone ist frei? Das ist ihr letzter Ausgang.',
  'pz.h1.end': 'Finde den Zug, der jedes Feld deines Raums nutzbar lässt. Ein Pfeil, der ihn teilt oder eine Sackgasse lässt, kostet einen Zug.',
  'pz.hintText': 'Beginne mit einer leuchtenden Amazone.',
  'pz.bl.reach': '{m} lässt den Gegner nicht in {n} ohne Zug.', 'pz.bl.last': 'Nach {m} kann der Gegner noch ziehen.',
  'pz.bl.trap': 'Nach {m} ist noch ein Ausgang offen.', 'pz.bl.end': '{m} schneidet Felder ab, und dir gehen zuerst die Züge aus.',
  'pz.again': 'Denk noch einmal nach.', 'pz.best': 'Die Lösung war {b}.', 'pz.reply': 'Der Gegner spielt {m}. Noch {n}.',
  'pz.solvedSub': 'Der Gegner hatte nach {n} Zügen keinen Zug mehr.', 'pz.solvedTrap': 'Eine gegnerische Amazone ist eingesperrt.', 'pz.solvedEnd': 'Jetzt hältst du bis zum Schluss länger durch als der Gegner.',
},
